#include <stdio.h>

int estoque[505][505];

int main() {
    int M, N;
    if (scanf("%d %d", &M, &N) != 2) return 0;

    for (int i = 1; i <= M; i++) {
        for (int j = 1; j <= N; j++) {
            scanf("%d", &estoque[i][j]);
        }
    }

    int P;
    if (scanf("%d", &P) != 1) return 0;

    int total_vendas = 0;
    for (int k = 0; k < P; k++) {
        int I, J;
        scanf("%d %d", &I, &J);
        if (estoque[I][J] > 0) {
            estoque[I][J]--;
            total_vendas++;
        }
    }

    printf("%d\n", total_vendas);

    return 0;
}
